#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    int left = 0, right = strlen(s) - 1;
    while (left < right) {
        char temp = s[left];
        s[left++] = s[right];
        s[right--] = temp;
    }
}

int main() {
    char text[] = "stack frames";
    reverse(text);
    printf("%s\n", text);
    return 0;
}
